import{_ as o,o as t,c as a,a2 as i}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md"}'),n={name:"guide/architecture.md"};function r(s,e,c,d,l,h){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><h2 id="the-governing-stance" tabindex="-1">The governing stance <a class="header-anchor" href="#the-governing-stance" aria-label="Permalink to &quot;The governing stance&quot;">​</a></h2><p><strong>helix is un-opinionated, twine is opinionated, spool is the opt-in middle.</strong> If something feels like a <em>shortcut</em> or a <em>best practice</em> rather than a primitive, it does not belong in helix - it gets pushed up to spool or twine instead.</p><p>Concretely:</p><ul><li><code>helix</code> provides <strong>mechanism</strong>: typed values, commands, and codegen for a given Minecraft version. It ships no bundled gameplay patterns and no opinions about how a pack is composed. When a feature feels like a shortcut, it doesn&#39;t go here.</li><li><code>spool</code> is the <strong>convenience layer</strong>: composed helpers built only on helix&#39;s public API, delivered as opt-in <code>KitPlugin</code>s. Nothing is on by default - you install exactly the plugins you want.</li><li><code>twine</code> is the <strong>opinionated framework</strong>: a NestJS-style module/area/lifecycle system that dictates how a whole pack is composed - which features are enabled, how they nest, and when their behaviour runs. Where helix refuses to dictate structure, twine <em>is</em> the structure.</li><li><code>lab</code> and <code>unravel</code> are consumers: <code>lab</code> is a sandbox of concrete features built on twine + spool; <code>unravel</code> is a plain-helix worked example with no framework at all.</li></ul><h2 id="how-the-layers-link" tabindex="-1">How the layers link <a class="header-anchor" href="#how-the-layers-link" aria-label="Permalink to &quot;How the layers link&quot;">​</a></h2><p>The packages consume each other&#39;s <strong>built <code>dist/</code></strong> via <code>file:../&lt;pkg&gt;</code> links in <code>package.json</code> (symlinked into <code>node_modules</code>), not source directly. This means:</p><ul><li>After changing a package&#39;s source, you must rebuild it (<code>npm run build</code>) before any consumer sees the new types or behaviour. A stale <code>dist/</code> silently hides breaking changes.</li><li>Build <strong>downward-up</strong>: helix first, then spool and twine, then lab and unravel.</li></ul><h2 id="compilation-model-helix" tabindex="-1">Compilation model (helix) <a class="header-anchor" href="#compilation-model-helix" aria-label="Permalink to &quot;Compilation model (helix)&quot;">​</a></h2><p>A pack is authored as fluent TypeScript against a <code>Datapack</code> instance pinned to a specific <code>VersionProfile</code>. Authoring builds an AST; codegen lowers that AST to an IR and renders it to <code>.mcfunction</code> text and tag/resource JSON - version-aware, so the same source can emit correct, different output across Minecraft versions (folder names, pack format, command grammar, registry membership).</p><p>Two output forms exist side-by-side:</p><ul><li><code>dp.writeDatapack(path)</code> - writes the <code>data/</code> tree to disk.</li><li><code>buildDatapack(dp)</code> - the same codegen, in memory, returning a <code>path → contents</code> map. This is what <code>dp.report()</code> (cost analysis) and <code>validateDatapack()</code> (mcdoc JSON validation) both build on, and it&#39;s the seam a future browser-based live preview would use.</li></ul><h2 id="typed-concepts-not-strings" tabindex="-1">Typed concepts, not strings <a class="header-anchor" href="#typed-concepts-not-strings" aria-label="Permalink to &quot;Typed concepts, not strings&quot;">​</a></h2><p>Every layer shares one rule: build domain values with their typed classes - <code>Selector</code>, <code>Pos</code>, <code>Block</code>, <code>Item</code>, <code>Nbt</code>, <code>Id</code>, <code>Score</code> - and let them render version-aware. Command handlers never string-interpolate fragments like <code>@a[distance=..6]</code> or <code>{Health:20f}</code>. If the typed API can&#39;t yet express a concept, that&#39;s a signal to extend the API, not to drop to a raw string.</p><h2 id="where-to-go-deeper" tabindex="-1">Where to go deeper <a class="header-anchor" href="#where-to-go-deeper" aria-label="Permalink to &quot;Where to go deeper&quot;">​</a></h2><ul><li><a href="/guide/helix.html">Helix</a> - the compiler core: AST/IR, command architecture, version profiles, cost reporting, JSON validation.</li><li><a href="/guide/spool.html">Spool</a> - the <code>KitPlugin</code> system and the plugin catalog.</li><li><a href="/guide/twine.html">Twine</a> - module/area/lifecycle composition, items, state machines.</li></ul>',16)])])}const m=o(n,[["render",r]]);export{u as __pageData,m as default};
